import json, sys
sys.path.insert(0,'/workspace/tmp/tests')

def parse(d):
    cells = d['cells']; banks = [[int(w,16) for w in b] for b in d['banks']]
    def rec(stage, cell):
        w = banks[stage][cell>>1]; off = (cell&1)*128
        return (w >> off) & ((1<<128)-1) if False else (w >> off)
    out=[]
    def g(w,off,n): return (w>>off)&((1<<n)-1)
    seen=set()
    def walk(stage, cell, origin, depth, tag):
        if (stage,cell) in seen: print(' '*depth, 'ALIAS'); return
        seen.add((stage,cell))
        w = banks[stage][cell>>1] >> ((cell&1)*128)
        typ = g(w,0,3); bmp=g(w,3,22)
        s = '%s[st%d c%d] %s d%d o%d bmp=%d' % (tag, stage,cell, {1:'T1',2:'T2',3:'T3',4:'T4',5:'T5'}[typ], depth, origin, bmp)
        if typ in (4,5):
            n = 1 if typ==4 else 2
            for k in range(n):
                frag=g(w,25+94*k,64); l=g(w,89+94*k,8); hop=g(w,97+94*k,22)
                s += ' | pfx frag=%x l=%d hop=%d' % (frag,l,hop)
        else:
            bid=g(w,25,16); nb=g(w,41,22)
            pat = int(d['bitmaps'][bid],16) if bid < len(d['bitmaps']) else -1
            s += ' | bid=%d pat=%x nibase=%d' % (bid,pat,nb)
            if typ==3:
                s += ' bulk=%x base=%d bstage=%d' % (g(w,63,64),g(w,127,22),g(w,149,4))
                for k in range(3):
                    raw=g(w,153+32*k,32); s += ' d%d=%x'%(k,raw)
            else:
                cnt = 2 if typ==1 else 6
                for k in range(cnt):
                    raw=g(w,63+32*k,32)
                    if raw==15<<6: s+=' | -'
                    else: s += ' | k%d->(st%d,c%d)'%(raw&0x3F,(raw>>6)&0xF,(raw>>10)&0x3FFFFF)
        print(s)
        if typ in (1,2):
            cnt = 2 if typ==1 else 6
            for k in range(cnt):
                raw=g(w,63+32*k,32)
                if raw!=15<<6: walk((raw>>6)&0xF,(raw>>10)&0x3FFFFF,origin,depth+6,'  '*depth)
        elif typ==3:
            bb=g(w,63,64); bs=g(w,127,22); bstage=g(w,149,4); rank=0
            for v in range(64):
                if bb>>v&1:
                    walk(bstage, bs+2*rank, origin, depth+6, '  '*depth); rank+=1
            for k in range(3):
                raw=g(w,153+32*k,32)
                if raw!=15<<6: walk((raw>>6)&0xF,(raw>>10)&0x3FFFFF,origin,depth+6,'  '*depth)
    if d['root'] is not None: walk(d['root'][0], d['root'][1], 0, 0, 'root0 ')
    for e in d['front16']: walk(e[1][0],e[1][1],16,16,'f16 %s '%e[0])
    for e in d['front64']: walk(e[1][0],e[1][1],64,64,'f64 %s '%e[0])
